// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *AutomationScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(automation.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// AutomationScopedUpsertOne is the "upsert" of one Automation.
type AutomationScopedUpsertOne struct {
	x *AutomationScopedCreate
	u *AutomationUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_AutomationScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_AutomationScopedUpsertOne               = "Automation"
	RoleOf_AutomationScopedUpsertOne_UpdateNewValues = RoleWrite
	RoleOf_AutomationScopedUpsertOne_Ignore          = RoleWrite
	RoleOf_AutomationScopedUpsertOne_DoNothing       = RoleWrite
	RoleOf_AutomationScopedUpsertOne_Update          = RoleWrite
	RoleOf_AutomationScopedUpsertOne_Exec            = RoleWrite
	RoleOf_AutomationScopedUpsertOne_ID              = RoleWrite
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *AutomationScopedCreate) OnConflictColumns(columns ...string) *AutomationScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *AutomationScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *AutomationScopedUpsertOne {
	return &AutomationScopedUpsertOne{x: x, u: x.b.OnConflict((&AutomationScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *AutomationScopedUpsertOne) UpdateNewValues() *AutomationScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *AutomationScopedUpsertOne) Ignore() *AutomationScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *AutomationScopedUpsertOne) DoNothing() *AutomationScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *AutomationScopedUpsertOne) Update(set func(*AutomationScopedUpsert)) *AutomationScopedUpsertOne {
	u.u.Update(func(s *AutomationUpsert) { set(&AutomationScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *AutomationScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *AutomationScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *AutomationScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.Automation.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeAutomation("create", nil, row))
	})
	return id, err
}

// AutomationScopedUpsertBulk is the "upsert" of several Automation entities.
type AutomationScopedUpsertBulk struct {
	b       *AutomationScopedCreateBulk
	t       *AutomationScoped
	columns []string
	opts    []func(*AutomationUpsertBulk)
}

const (
	TypeOf_AutomationScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_AutomationScopedUpsertBulk               = "Automation"
	RoleOf_AutomationScopedUpsertBulk_UpdateNewValues = RoleWrite
	RoleOf_AutomationScopedUpsertBulk_Ignore          = RoleWrite
	RoleOf_AutomationScopedUpsertBulk_DoNothing       = RoleWrite
	RoleOf_AutomationScopedUpsertBulk_Update          = RoleWrite
	RoleOf_AutomationScopedUpsertBulk_Exec            = RoleWrite
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *AutomationScopedCreateBulk) OnConflictColumns(columns ...string) *AutomationScopedUpsertBulk {
	return &AutomationScopedUpsertBulk{b: b, t: &AutomationScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *AutomationScopedUpsertBulk) UpdateNewValues() *AutomationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *AutomationUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *AutomationScopedUpsertBulk) Ignore() *AutomationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *AutomationUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *AutomationScopedUpsertBulk) DoNothing() *AutomationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *AutomationUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *AutomationScopedUpsertBulk) Update(set func(*AutomationScopedUpsert)) *AutomationScopedUpsertBulk {
	u.opts = append(u.opts, func(r *AutomationUpsertBulk) {
		r.Update(func(s *AutomationUpsert) { set(&AutomationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *AutomationScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

