func (x *AutomationScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyAutomationVersion(ctx, m.VersionsIDs()); err != nil {
		return fmt.Errorf("versions: %w", err)
	}
	if err := x.s.verifyAutomationVersion(ctx, m.LiveVersionIDs()); err != nil {
		return fmt.Errorf("live_version: %w", err)
	}
	if err := x.s.verifyAutomationVersion(ctx, m.DraftVersionIDs()); err != nil {
		return fmt.Errorf("draft_version: %w", err)
	}
	if err := x.s.verifyAutomationRun(ctx, m.RunsIDs()); err != nil {
		return fmt.Errorf("runs: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *AutomationScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Automation.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Save(ctx); err != nil {
				return err
			}
			ids := make([]int64, len(before))
			for i, row := range before {
				ids[i] = row.ID
			}
			after, err := ts.c.Automation.Query().Where(automation.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			byID := make(map[int64]*Automation, len(after))
			for _, row := range after {
				byID[row.ID] = row
			}
			for _, row := range before {
				if now, ok := byID[row.ID]; ok {
					if err := ts.record(ctx, auditChangeAutomation("update", row, now)); err != nil {
						return err
					}
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *AutomationScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

