// BroadcastRecipientScopedCreateBulk creates several BroadcastRecipient entities of one Workspace at once.
type BroadcastRecipientScopedCreateBulk struct {
	s  *Scoped
	xs []*BroadcastRecipientScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *BroadcastRecipientScoped) CreateBulk(xs ...*BroadcastRecipientScopedCreate) *BroadcastRecipientScopedCreateBulk {
	return &BroadcastRecipientScopedCreateBulk{s: t.s, xs: xs}
}

func (b *BroadcastRecipientScopedCreateBulk) raw(ctx context.Context) (*BroadcastRecipientCreateBulk, error) {
	builders := make([]*BroadcastRecipientCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("BroadcastRecipient: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.BroadcastRecipient.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *BroadcastRecipientScopedCreateBulk) check(ctx context.Context) error {
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().BroadcastIDs()...)
		}
		if err := b.s.verifyBroadcast(ctx, ids); err != nil {
			return fmt.Errorf("broadcast: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().ContactIDs()...)
		}
		if err := b.s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	return nil
}

// Save verifies every builder's references, then creates the BroadcastRecipient entities.
func (b *BroadcastRecipientScopedCreateBulk) Save(ctx context.Context) ([]*BroadcastRecipient, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *BroadcastRecipientScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

