func (x *ContactScopedUpdateOne) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyVisitor(ctx, m.VisitorsIDs()); err != nil {
		return fmt.Errorf("visitors: %w", err)
	}
	if err := x.s.verifyBinding(ctx, m.BindingsIDs()); err != nil {
		return fmt.Errorf("bindings: %w", err)
	}
	if err := x.s.verifyStartToken(ctx, m.StartTokensIDs()); err != nil {
		return fmt.Errorf("start_tokens: %w", err)
	}
	if err := x.s.verifyEvent(ctx, m.EventsIDs()); err != nil {
		return fmt.Errorf("events: %w", err)
	}
	if err := x.s.verifyOrder(ctx, m.OrdersIDs()); err != nil {
		return fmt.Errorf("orders: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the Contact.
func (x *ContactScopedUpdateOne) Save(ctx context.Context) (*Contact, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *Contact
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.Contact.Query().Where(x.b.mutation.predicates...).Where(contact.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeContact("update", before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *ContactScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_ContactScopedUpdateOne       = TypeScopedUpdate
	EntityOf_ContactScopedUpdateOne     = "Contact"
	RoleOf_ContactScopedUpdateOne_Where = RoleWrite
	RoleOf_ContactScopedUpdateOne_Save  = RoleWrite
	RoleOf_ContactScopedUpdateOne_Exec  = RoleWrite
)

// ContactScopedUpdate wraps ContactUpdate: a conditional bulk update of one Workspace.
type ContactScopedUpdate struct {
	s *Scoped
	b *ContactUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Contact entities of the Workspace that match the predicates.
func (t *ContactScoped) Update() *ContactScopedUpdate {
	return &ContactScopedUpdate{s: t.s, b: t.s.c.Contact.Update().Where(contact.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *ContactScopedUpdate) Where(ps ...predicate.Contact) *ContactScopedUpdate {
	x.b.Where(ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *ContactScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *ContactScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(contact.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
	}
	return x
}

