// Save verifies the references against the Workspace, then creates the CustomField.
func (x *CustomFieldScopedCreate) Save(ctx context.Context) (*CustomField, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *CustomField
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeCustomField("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *CustomFieldScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

