// Save verifies the references against the Workspace, then creates the EmailTemplate.
func (x *EmailTemplateScopedCreate) Save(ctx context.Context) (*EmailTemplate, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *EmailTemplate
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeEmailTemplate("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *EmailTemplateScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// EmailTemplateScopedCreateBulk creates several EmailTemplate entities of one Workspace at once.
type EmailTemplateScopedCreateBulk struct {
	s  *Scoped
	xs []*EmailTemplateScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *EmailTemplateScoped) CreateBulk(xs ...*EmailTemplateScopedCreate) *EmailTemplateScopedCreateBulk {
	return &EmailTemplateScopedCreateBulk{s: t.s, xs: xs}
}

func (b *EmailTemplateScopedCreateBulk) raw(ctx context.Context) (*EmailTemplateCreateBulk, error) {
	builders := make([]*EmailTemplateCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("EmailTemplate: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.EmailTemplate.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *EmailTemplateScopedCreateBulk) check(ctx context.Context) error {
	return nil
}

// Save verifies every builder's references, then creates the EmailTemplate entities.
func (b *EmailTemplateScopedCreateBulk) Save(ctx context.Context) ([]*EmailTemplate, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*EmailTemplate
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeEmailTemplate("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *EmailTemplateScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

