// ---------------------------------------------------------------- create bulk

// OrderScopedCreateBulk creates several Order entities of one Workspace at once.
type OrderScopedCreateBulk struct {
	s  *Scoped
	xs []*OrderScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *OrderScoped) CreateBulk(xs ...*OrderScopedCreate) *OrderScopedCreateBulk {
	return &OrderScopedCreateBulk{s: t.s, xs: xs}
}

func (b *OrderScopedCreateBulk) raw(ctx context.Context) (*OrderCreateBulk, error) {
	builders := make([]*OrderCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Order: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.Order.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *OrderScopedCreateBulk) check(ctx context.Context) error {
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().ContactIDs()...)
		}
		if err := b.s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().BroadcastIDs()...)
		}
		if err := b.s.verifyBroadcast(ctx, ids); err != nil {
			return fmt.Errorf("broadcast: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().AutomationIDs()...)
		}
		if err := b.s.verifyAutomation(ctx, ids); err != nil {
			return fmt.Errorf("automation: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().MovementsIDs()...)
		}
		if err := b.s.verifyOrderMovement(ctx, ids); err != nil {
			return fmt.Errorf("movements: %w", err)
		}
	}
	return nil
}

// Save verifies every builder's references, then creates the Order entities.
func (b *OrderScopedCreateBulk) Save(ctx context.Context) ([]*Order, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *OrderScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

