// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *OutboundMessageScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(outboundmessage.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// OutboundMessageScopedUpsertOne is the "upsert" of one OutboundMessage.
type OutboundMessageScopedUpsertOne struct {
	x *OutboundMessageScopedCreate
	u *OutboundMessageUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_OutboundMessageScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_OutboundMessageScopedUpsertOne               = "OutboundMessage"
	RoleOf_OutboundMessageScopedUpsertOne_UpdateNewValues = RoleWrite
	RoleOf_OutboundMessageScopedUpsertOne_Ignore          = RoleWrite
	RoleOf_OutboundMessageScopedUpsertOne_DoNothing       = RoleWrite
	RoleOf_OutboundMessageScopedUpsertOne_Update          = RoleWrite
	RoleOf_OutboundMessageScopedUpsertOne_Exec            = RoleWrite
	RoleOf_OutboundMessageScopedUpsertOne_ID              = RoleWrite
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *OutboundMessageScopedCreate) OnConflictColumns(columns ...string) *OutboundMessageScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *OutboundMessageScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *OutboundMessageScopedUpsertOne {
	return &OutboundMessageScopedUpsertOne{x: x, u: x.b.OnConflict((&OutboundMessageScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *OutboundMessageScopedUpsertOne) UpdateNewValues() *OutboundMessageScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *OutboundMessageScopedUpsertOne) Ignore() *OutboundMessageScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *OutboundMessageScopedUpsertOne) DoNothing() *OutboundMessageScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *OutboundMessageScopedUpsertOne) Update(set func(*OutboundMessageScopedUpsert)) *OutboundMessageScopedUpsertOne {
	u.u.Update(func(s *OutboundMessageUpsert) { set(&OutboundMessageScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *OutboundMessageScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *OutboundMessageScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	return u.u.ID(ctx)
}

