// RuleScoped reaches Rule entities of one Workspace.
type RuleScoped struct{ s *Scoped }

// Rule returns the Rule entities of the Workspace.
func (s *Scoped) Rule() *RuleScoped { return &RuleScoped{s: s} }

const (
	TypeOf_RuleScoped                    = TypeWrapper
	EntityOf_RuleScoped                  = "Rule"
	RoleOf_Scoped_Rule                   = RoleNone
	RoleOf_RuleScoped_Query              = RoleRead
	RoleOf_RuleScoped_QueryWithDiscarded = RoleRead
	RoleOf_RuleScoped_Discard            = RoleStart
	RoleOf_RuleScoped_Get                = RoleRead
	RoleOf_RuleScoped_PurgeOneID         = RoleStart
	RoleOf_RuleScoped_UpdateOneID        = RoleStart
	RoleOf_RuleScoped_Purge              = RoleStart
	RoleOf_RuleScoped_Create             = RoleStart
	RoleOf_RuleScoped_CreateBulk         = RoleStart
	RoleOf_RuleScoped_Update             = RoleStart
)

// Query returns a Rule query already confined to the Workspace, hiding discarded rows
// (a list query; QueryWithDiscarded sees them too).
func (t *RuleScoped) Query() *RuleQuery {
	return t.s.c.Rule.Query().Where(rule.WorkspaceID(t.s.ws), rule.DiscardedAtIsNil())
}

// QueryWithDiscarded returns a Rule query confined to the Workspace that also sees discarded rows.
func (t *RuleScoped) QueryWithDiscarded() *RuleQuery {
	return t.s.c.Rule.Query().Where(rule.WorkspaceID(t.s.ws))
}

// Get returns the Rule with the id, discarded or not; a row of another Workspace is not found.
func (t *RuleScoped) Get(ctx context.Context, id int64) (*Rule, error) {
	return t.QueryWithDiscarded().Where(rule.ID(id)).Only(ctx)
}

// Discard stamps discarded_at, at `at`, on the kept Rule with the id (ps fence it further); a row of
// another Workspace, an already discarded row or one a predicate excludes is not found. A discarded
// row is never brought back (ADR 0100): the generated client has no Undiscard.
func (t *RuleScoped) Discard(ctx context.Context, id int64, at time.Time, ps ...predicate.Rule) error {
	where := append([]predicate.Rule{rule.ID(id), rule.WorkspaceID(t.s.ws), rule.DiscardedAtIsNil()}, ps...)
	write := func(c *Client) (*Rule, error) {
		return c.Rule.UpdateOneID(id).Where(where...).SetDiscardedAt(at).Save(ctx)
	}
	if t.s.auditing() {
		return t.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Rule.Query().Where(where...).Only(ctx)
			if err != nil {
				return err
			}
			after, err := write(ts.c)
			if err != nil {
				return err
			}
			return ts.record(ctx, auditChangeRule("discard", before, after))
		})
	}
	_, err := write(t.s.c)
	return err
}

