// Save verifies the references against the Workspace, then creates the Rule.
func (x *RuleScopedCreate) Save(ctx context.Context) (*Rule, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var created *Rule
		err := x.s.audited(ctx, func(ts *Scoped) error {
			x.b.auditRebind(ts.c)
			var err error
			if created, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeRule("create", nil, created))
		})
		return created, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *RuleScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// RuleScopedCreateBulk creates several Rule entities of one Workspace at once.
type RuleScopedCreateBulk struct {
	s  *Scoped
	xs []*RuleScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *RuleScoped) CreateBulk(xs ...*RuleScopedCreate) *RuleScopedCreateBulk {
	return &RuleScopedCreateBulk{s: t.s, xs: xs}
}

func (b *RuleScopedCreateBulk) raw(ctx context.Context) (*RuleCreateBulk, error) {
	builders := make([]*RuleCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Rule: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.Rule.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *RuleScopedCreateBulk) check(ctx context.Context) error {
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().VersionsIDs()...)
		}
		if err := b.s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("versions: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().LiveVersionIDs()...)
		}
		if err := b.s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("live_version: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().DraftVersionIDs()...)
		}
		if err := b.s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("draft_version: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().FiringsIDs()...)
		}
		if err := b.s.verifyRuleFiring(ctx, ids); err != nil {
			return fmt.Errorf("firings: %w", err)
		}
	}
	return nil
}

// Save verifies every builder's references, then creates the Rule entities.
func (b *RuleScopedCreateBulk) Save(ctx context.Context) ([]*Rule, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	if b.s.auditing() {
		var created []*Rule
		err := b.s.audited(ctx, func(ts *Scoped) error {
			raw.auditRebind(ts.c)
			var err error
			if created, err = raw.Save(ctx); err != nil {
				return err
			}
			for _, row := range created {
				if err := ts.record(ctx, auditChangeRule("create", nil, row)); err != nil {
					return err
				}
			}
			return nil
		})
		return created, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *RuleScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

