func (x *RuleScopedUpdateOne) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyRuleVersion(ctx, m.VersionsIDs()); err != nil {
		return fmt.Errorf("versions: %w", err)
	}
	if err := x.s.verifyRuleVersion(ctx, m.LiveVersionIDs()); err != nil {
		return fmt.Errorf("live_version: %w", err)
	}
	if err := x.s.verifyRuleVersion(ctx, m.DraftVersionIDs()); err != nil {
		return fmt.Errorf("draft_version: %w", err)
	}
	if err := x.s.verifyRuleFiring(ctx, m.FiringsIDs()); err != nil {
		return fmt.Errorf("firings: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the Rule.
func (x *RuleScopedUpdateOne) Save(ctx context.Context) (*Rule, error) {
	return x.save(ctx, "update")
}

// save keeps a machine's deletion verb while sharing the reference checks and audit capture.
func (x *RuleScopedUpdateOne) save(ctx context.Context, verb string) (*Rule, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *Rule
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.Rule.Query().Where(x.b.mutation.predicates...).Where(rule.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeRule(verb, before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *RuleScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

