// SegmentScoped reaches Segment entities of one Workspace.
type SegmentScoped struct{ s *Scoped }

// Segment returns the Segment entities of the Workspace.
func (s *Scoped) Segment() *SegmentScoped { return &SegmentScoped{s: s} }

const (
	TypeOf_SegmentScoped                   = TypeWrapper
	EntityOf_SegmentScoped                 = "Segment"
	RoleOf_Scoped_Segment                  = RoleNone
	RoleOf_SegmentScoped_Query             = RoleRead
	RoleOf_SegmentScoped_QueryWithArchived = RoleRead
	RoleOf_SegmentScoped_QueryArchived     = RoleRead
	RoleOf_SegmentScoped_Archive           = RoleStart
	RoleOf_SegmentScoped_Unarchive         = RoleStart
	RoleOf_SegmentScoped_Get               = RoleRead
	RoleOf_SegmentScoped_PurgeOneID        = RoleStart
	RoleOf_SegmentScoped_UpdateOneID       = RoleStart
	RoleOf_SegmentScoped_Purge             = RoleStart
	RoleOf_SegmentScoped_Create            = RoleStart
	RoleOf_SegmentScoped_CreateBulk        = RoleStart
	RoleOf_SegmentScoped_Update            = RoleStart
)

// Query returns a Segment query already confined to the Workspace, hiding archived rows
// (a list query; QueryWithArchived sees them too).
func (t *SegmentScoped) Query() *SegmentQuery {
	return t.s.c.Segment.Query().Where(segment.WorkspaceID(t.s.ws), segment.ArchivedAtIsNil())
}

// QueryWithArchived returns a Segment query confined to the Workspace that also sees archived rows.
func (t *SegmentScoped) QueryWithArchived() *SegmentQuery {
	return t.s.c.Segment.Query().Where(segment.WorkspaceID(t.s.ws))
}

// QueryArchived returns a Segment query confined to the Workspace that sees only archived rows
// (the archived view).
func (t *SegmentScoped) QueryArchived() *SegmentQuery {
	return t.QueryWithArchived().Where(segment.ArchivedAtNotNil())
}

// Get returns the Segment with the id, archived or not; a row of another Workspace is not found.
func (t *SegmentScoped) Get(ctx context.Context, id int64) (*Segment, error) {
	return t.QueryWithArchived().Where(segment.ID(id)).Only(ctx)
}

// Archive stamps archived_at, at `at`, on the kept Segment with the id (ps fence it further); a row of
// another Workspace, an already archived row or one a predicate excludes is not found.
func (t *SegmentScoped) Archive(ctx context.Context, id int64, at time.Time, ps ...predicate.Segment) error {
	where := append([]predicate.Segment{segment.ID(id), segment.WorkspaceID(t.s.ws), segment.ArchivedAtIsNil()}, ps...)
	return t.setArchived(ctx, id, where, "archive", func(u *SegmentUpdateOne) { u.SetArchivedAt(at) })
}

// Unarchive clears archived_at on the Segment with the id. Unarchiving a kept row changes
// nothing; only a row that does not exist in the Workspace is not found.
func (t *SegmentScoped) Unarchive(ctx context.Context, id int64) error {
	where := []predicate.Segment{segment.ID(id), segment.WorkspaceID(t.s.ws), segment.ArchivedAtNotNil()}
	err := t.setArchived(ctx, id, where, "unarchive", func(u *SegmentUpdateOne) { u.ClearArchivedAt() })
	if !IsNotFound(err) {
		return err
	}
	_, err = t.Get(ctx, id)
	return err
}

func (t *SegmentScoped) setArchived(ctx context.Context, id int64, where []predicate.Segment, verb string, set func(*SegmentUpdateOne)) error {
	write := func(c *Client) (*Segment, error) {
		u := c.Segment.UpdateOneID(id).Where(where...)
		set(u)
		return u.Save(ctx)
	}
	if t.s.auditing() {
		return t.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Segment.Query().Where(where...).Only(ctx)
			if err != nil {
				return err
			}
			after, err := write(ts.c)
			if err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSegment(verb, before, after))
		})
	}
	_, err := write(t.s.c)
	return err
}

// SegmentScopedDeleteOne wraps SegmentDeleteOne.
type SegmentScopedDeleteOne struct {
	s *Scoped
	b *SegmentDeleteOne
}

// PurgeOneID physically removes the Segment with the id; a row of another Workspace is not found.
func (t *SegmentScoped) PurgeOneID(id int64) *SegmentScopedDeleteOne {
	return &SegmentScopedDeleteOne{s: t.s, b: t.s.c.Segment.DeleteOneID(id).Where(segment.WorkspaceID(t.s.ws))}
}

// Where appends predicates the row must also match (fencing).
func (x *SegmentScopedDeleteOne) Where(ps ...predicate.Segment) *SegmentScopedDeleteOne {
	x.b.Where(ps...)
	return x
}

const (
	TypeOf_SegmentScopedDeleteOne       = TypeScopedDelete
	EntityOf_SegmentScopedDeleteOne     = "Segment"
	RoleOf_SegmentScopedDeleteOne_Where = RoleWrite
	RoleOf_SegmentScopedDeleteOne_Exec  = RoleWrite
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *SegmentScopedDeleteOne) Exec(ctx context.Context) error {
	if x.s.auditing() {
		return x.s.audited(ctx, func(ts *Scoped) error {
			before, err := ts.c.Segment.Query().Where(x.b._d.mutation.predicates...).Only(ctx)
			if err != nil {
				return err
			}
			x.b._d.auditRebind(ts.c)
			if err := x.b.Exec(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangeSegment("delete", before, nil))
		})
	}
	return x.b.Exec(ctx)
}

// SegmentScopedDelete wraps SegmentDelete.
type SegmentScopedDelete struct {
	s *Scoped
	b *SegmentDelete
}

// Purge physically removes the Segment entities of the Workspace that match the predicates.
func (t *SegmentScoped) Purge() *SegmentScopedDelete {
	return &SegmentScopedDelete{s: t.s, b: t.s.c.Segment.Delete().Where(segment.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *SegmentScopedDelete) Where(ps ...predicate.Segment) *SegmentScopedDelete {
	x.b.Where(ps...)
	return x
}

const (
	TypeOf_SegmentScopedDelete       = TypeScopedDelete
	EntityOf_SegmentScopedDelete     = "Segment"
	RoleOf_SegmentScopedDelete_Where = RoleWrite
	RoleOf_SegmentScopedDelete_Exec  = RoleWrite
)

// Exec deletes the rows and returns how many were deleted.
func (x *SegmentScopedDelete) Exec(ctx context.Context) (int, error) {
	if x.s.auditing() {
		var n int
		err := x.s.audited(ctx, func(ts *Scoped) error {
			rows, err := ts.c.Segment.Query().Where(x.b.mutation.predicates...).All(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if n, err = x.b.Exec(ctx); err != nil {
				return err
			}
			for _, row := range rows {
				if err := ts.record(ctx, auditChangeSegment("delete", row, nil)); err != nil {
					return err
				}
			}
			return nil
		})
		return n, err
	}
	return x.b.Exec(ctx)
}

