// ---------------------------------------------------------------- create bulk

// SuppressionScopedCreateBulk creates several Suppression entities of one Workspace at once.
type SuppressionScopedCreateBulk struct {
	s  *Scoped
	xs []*SuppressionScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *SuppressionScoped) CreateBulk(xs ...*SuppressionScopedCreate) *SuppressionScopedCreateBulk {
	return &SuppressionScopedCreateBulk{s: t.s, xs: xs}
}

func (b *SuppressionScopedCreateBulk) raw(ctx context.Context) (*SuppressionCreateBulk, error) {
	builders := make([]*SuppressionCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Suppression: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.Suppression.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *SuppressionScopedCreateBulk) check(ctx context.Context) error {
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().ContactIDs()...)
		}
		if err := b.s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	return nil
}

// Save verifies every builder's references, then creates the Suppression entities.
func (b *SuppressionScopedCreateBulk) Save(ctx context.Context) ([]*Suppression, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *SuppressionScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

