func (t *TagScoped) DeleteOneID(id int64) *TagScopedDeleteOne {
	return &TagScopedDeleteOne{s: t.s, b: t.s.c.Tag.DeleteOneID(id).Where(tag.WorkspaceID(t.s.ws))}
}

