// CreateBulk batches creates started on this Workspace.
func (t *TrackedLinkScoped) CreateBulk(xs ...*TrackedLinkScopedCreate) *TrackedLinkScopedCreateBulk {
	return &TrackedLinkScopedCreateBulk{s: t.s, xs: xs}
}

func (b *TrackedLinkScopedCreateBulk) raw(ctx context.Context) (*TrackedLinkCreateBulk, error) {
	builders := make([]*TrackedLinkCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("TrackedLink: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.TrackedLink.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *TrackedLinkScopedCreateBulk) check(ctx context.Context) error {
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().OutboundMessageIDs()...)
		}
		if err := b.s.verifyOutboundMessage(ctx, ids); err != nil {
			return fmt.Errorf("outbound_message: %w", err)
		}
	}
	return nil
}

// Save verifies every builder's references, then creates the TrackedLink entities.
func (b *TrackedLinkScopedCreateBulk) Save(ctx context.Context) ([]*TrackedLink, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *TrackedLinkScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_TrackedLinkScopedCreateBulk                   = TypeScopedCreate
	EntityOf_TrackedLinkScopedCreateBulk                 = "TrackedLink"
	RoleOf_TrackedLinkScopedCreateBulk_Save              = RoleWrite
	RoleOf_TrackedLinkScopedCreateBulk_Exec              = RoleWrite
	RoleOf_TrackedLinkScopedCreateBulk_OnConflictColumns = RoleStart
)

