// ---------------------------------------------------------------- create bulk

// VisitorScopedCreateBulk creates several Visitor entities of one Workspace at once.
type VisitorScopedCreateBulk struct {
	s  *Scoped
	xs []*VisitorScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *VisitorScoped) CreateBulk(xs ...*VisitorScopedCreate) *VisitorScopedCreateBulk {
	return &VisitorScopedCreateBulk{s: t.s, xs: xs}
}

func (b *VisitorScopedCreateBulk) raw(ctx context.Context) (*VisitorCreateBulk, error) {
	builders := make([]*VisitorCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("Visitor: builder of another scope: %w", ErrNotInWorkspace)
		}
		builders[i] = x.b
	}
	if err := b.check(ctx); err != nil {
		return nil, err
	}
	return b.s.c.Visitor.CreateBulk(builders...), nil
}

// check verifies the references of every builder against the Workspace, one query per
// reference for the whole batch rather than one per row.
func (b *VisitorScopedCreateBulk) check(ctx context.Context) error {
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().BindingsIDs()...)
		}
		if err := b.s.verifyBinding(ctx, ids); err != nil {
			return fmt.Errorf("bindings: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().StartTokensIDs()...)
		}
		if err := b.s.verifyStartToken(ctx, ids); err != nil {
			return fmt.Errorf("start_tokens: %w", err)
		}
	}
	{
		var ids []int64
		for _, x := range b.xs {
			ids = append(ids, x.b.Mutation().ContactIDs()...)
		}
		if err := b.s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	return nil
}

// Save verifies every builder's references, then creates the Visitor entities.
func (b *VisitorScopedCreateBulk) Save(ctx context.Context) ([]*Visitor, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *VisitorScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

