// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *WebhookEndpointScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(webhookendpoint.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// WebhookEndpointScopedUpsertOne is the "upsert" of one WebhookEndpoint.
type WebhookEndpointScopedUpsertOne struct {
	x *WebhookEndpointScopedCreate
	u *WebhookEndpointUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_WebhookEndpointScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_WebhookEndpointScopedUpsertOne               = "WebhookEndpoint"
	RoleOf_WebhookEndpointScopedUpsertOne_UpdateNewValues = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertOne_Ignore          = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertOne_DoNothing       = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertOne_Update          = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertOne_Exec            = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertOne_ID              = RoleWrite
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *WebhookEndpointScopedCreate) OnConflictColumns(columns ...string) *WebhookEndpointScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *WebhookEndpointScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *WebhookEndpointScopedUpsertOne {
	return &WebhookEndpointScopedUpsertOne{x: x, u: x.b.OnConflict((&WebhookEndpointScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *WebhookEndpointScopedUpsertOne) UpdateNewValues() *WebhookEndpointScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *WebhookEndpointScopedUpsertOne) Ignore() *WebhookEndpointScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *WebhookEndpointScopedUpsertOne) DoNothing() *WebhookEndpointScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *WebhookEndpointScopedUpsertOne) Update(set func(*WebhookEndpointScopedUpsert)) *WebhookEndpointScopedUpsertOne {
	u.u.Update(func(s *WebhookEndpointUpsert) { set(&WebhookEndpointScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *WebhookEndpointScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	if u.x.s.auditing() {
		_, err := u.audited(ctx)
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *WebhookEndpointScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	if u.x.s.auditing() {
		return u.audited(ctx)
	}
	return u.u.ID(ctx)
}

// audited runs a DO NOTHING upsert with its entry: an insert is a create, a conflict
// (sql.ErrNoRows) writes nothing and records nothing.
func (u *WebhookEndpointScopedUpsertOne) audited(ctx context.Context) (int64, error) {
	if !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.audited(ctx, func(ts *Scoped) error {
		u.x.b.auditRebind(ts.c)
		var err error
		if id, err = u.u.ID(ctx); err != nil {
			return err
		}
		row, err := ts.c.WebhookEndpoint.Get(ctx, id)
		if err != nil {
			return err
		}
		return ts.record(ctx, auditChangeWebhookEndpoint("create", nil, row))
	})
	return id, err
}

// WebhookEndpointScopedUpsertBulk is the "upsert" of several WebhookEndpoint entities.
type WebhookEndpointScopedUpsertBulk struct {
	b       *WebhookEndpointScopedCreateBulk
	t       *WebhookEndpointScoped
	columns []string
	opts    []func(*WebhookEndpointUpsertBulk)
}

const (
	TypeOf_WebhookEndpointScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_WebhookEndpointScopedUpsertBulk               = "WebhookEndpoint"
	RoleOf_WebhookEndpointScopedUpsertBulk_UpdateNewValues = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertBulk_Ignore          = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertBulk_DoNothing       = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertBulk_Update          = RoleWrite
	RoleOf_WebhookEndpointScopedUpsertBulk_Exec            = RoleWrite
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *WebhookEndpointScopedCreateBulk) OnConflictColumns(columns ...string) *WebhookEndpointScopedUpsertBulk {
	return &WebhookEndpointScopedUpsertBulk{b: b, t: &WebhookEndpointScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *WebhookEndpointScopedUpsertBulk) UpdateNewValues() *WebhookEndpointScopedUpsertBulk {
	u.opts = append(u.opts, func(r *WebhookEndpointUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *WebhookEndpointScopedUpsertBulk) Ignore() *WebhookEndpointScopedUpsertBulk {
	u.opts = append(u.opts, func(r *WebhookEndpointUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *WebhookEndpointScopedUpsertBulk) DoNothing() *WebhookEndpointScopedUpsertBulk {
	u.opts = append(u.opts, func(r *WebhookEndpointUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *WebhookEndpointScopedUpsertBulk) Update(set func(*WebhookEndpointScopedUpsert)) *WebhookEndpointScopedUpsertBulk {
	u.opts = append(u.opts, func(r *WebhookEndpointUpsertBulk) {
		r.Update(func(s *WebhookEndpointUpsert) { set(&WebhookEndpointScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *WebhookEndpointScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

